package cn.iocoder.yudao.module.statistics.job.dashboard;
import cn.iocoder.yudao.module.statistics.service.dashboard.DashboardTenantExecutor;import com.xxl.job.core.handler.annotation.XxlJob;import org.springframework.stereotype.Component;import jakarta.annotation.Resource;import java.time.*;import java.util.stream.IntStream;
@Component public class DashboardStatisticsJob { @Resource private DashboardTenantExecutor executor; @XxlJob("dashboardStatisticsJob") public void execute(){String mode=com.xxl.job.core.context.XxlJobHelper.getJobParam();LocalDate today=LocalDate.now(ZoneId.of("Asia/Shanghai"));if("TODAY_AND_YESTERDAY".equals(mode)){executor.recompute(today);executor.recompute(today.minusDays(1));}else if("FINALIZE_YESTERDAY".equals(mode)){executor.recompute(today.minusDays(1));}else if("ROLLING_7_COMPLETE_DAYS".equals(mode)){IntStream.rangeClosed(1,7).forEach(i->executor.recompute(today.minusDays(i)));}else throw new IllegalArgumentException("unsupported dashboard job mode");} }
